using UnityEngine;

namespace Showcase
{
    /// <summary>
    /// The materials and source prefabs of one showcase look, shared by the offline replay and the live view.
    /// Generated by ShowcaseBuilder; the prefab slots mirror the training scene's agent template.
    /// </summary>
    [CreateAssetMenu(menuName = "Showcase/Look")]
    public class ShowcaseLook : ScriptableObject
    {
        [Header("Training prefabs (read from the agent template in the training scene)")]
        public GameObject armPrefab;
        public GameObject ballPrefab;
        public GameObject targetPrefab;

        [Header("Materials")]
        public Material armShell;
        public Material handShell;
        public Material ball;
        public Material target;
        public Material targetHit;
        [Tooltip("Static scenery recorded from training, such as the ball's pedestal.")]
        public Material prop;

        [Header("Dressing")]
        [Tooltip("Rebuild sphere, capsule and box parts as dense rounded meshes.")]
        public bool smoothMeshes = true;
        [Tooltip("When set, every capsule part gets a joint sphere in this material at both ends.")]
        public Material joint;
        [Tooltip("When set, replaces the target's own mesh: a unit-radius dressing facing +Y, turned to the camera. " +
                 "A child named 'Shell' is the hit shockwave.")]
        public GameObject targetDressing;

        [Header("Effects")]
        [Tooltip("The glowing trail behind the ball in flight (additive, vertex-colored).")]
        public Material trail;
        [Tooltip("Sparks thrown out of a hit; falls back to targetHit.")]
        public Material spark;

        public Material MaterialFor(ActorKind kind, string partPath)
        {
            switch (kind)
            {
                case ActorKind.Ball: return ball;
                case ActorKind.Target: return target;
                case ActorKind.Prop: return prop != null ? prop : joint != null ? joint : armShell;
                default: return IsHandPart(partPath) ? handShell : armShell;
            }
        }

        static bool IsHandPart(string partPath)
        {
            string leaf = partPath.Substring(partPath.LastIndexOf('/') + 1).ToLowerInvariant();
            return leaf.StartsWith("finger") || leaf.StartsWith("thumb") || leaf.StartsWith("palm");
        }

        /// <summary>Applies the look to a live object spawned by the training scene.</summary>
        public void Restyle(Transform root, ActorKind kind)
        {
            foreach (var r in root.GetComponentsInChildren<MeshRenderer>(true))
            {
                var mat = MaterialFor(kind, r.transform == root ? r.name : r.transform.name);
                var mats = r.sharedMaterials;
                for (int i = 0; i < mats.Length; i++) mats[i] = mat;
                r.sharedMaterials = mats;
                r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;
                r.receiveShadows = true;
            }
        }
    }
}
